#ifndef _SENSORDRIVER_h
#define _SENSORDRIVER_h
#include "Common.h"

int minLight = 10;   // Negative start value means nothing has been read yet
int maxLight = 10;
int lightThreshold = 0;
unsigned long lastReadTime = 0;
const unsigned long adjustInterval = 10000; // recompute the threshold every 20 seconds

void adjustThreshold() {
  lightThreshold = (minLight + maxLight) / 2;
  Serial.print("New light threshold computed: ");
  Serial.println(lightThreshold);
}

bool isLightOn() {
  int light = analogRead(LDR_PIN);
  if (light < minLight) minLight = light;
  if (light > maxLight) maxLight = light;
  adjustThreshold();      
  bool lightPresent = (light < lightThreshold);  
  if (!lightPresent) {
    Serial.print("No light: " );
     Serial.println(light);
  } else {
    Serial.print("Light present: ");
     Serial.println(light);
  }
  return lightPresent;
}

bool isMovementDetected()
{
  int currentStateMovement = digitalRead(PIR_PIN);

  if (currentStateMovement != lastStateMovement)
  {
    lastTriggerTime = millis();               // Update the time of the last state change
    lastStateMovement = currentStateMovement; // Update the last recorded state
    movementDetected = true;                  // A state change was detected
  }

  // Check whether less than 5 seconds have passed since the last state change
  if (movementDetected && millis() - lastTriggerTime < 3000)
  {
    Serial.println("Movement DETECTED........ 130");
    return true; // Returns true if a state change happened within 5 seconds
  }

  // Check whether more than 5 seconds have passed since the last state change
  if (millis() - lastTriggerTime >= 3000)
  {
    movementDetected = false; // Clear the state-change flag
  }

  return false; // If no condition matches, return false
}

bool isSoundDetected()
{
  int sound = digitalRead(SOUND_PIN);
  if (sound == HIGH)
  {
    Serial.println("Sound detected");
    return true;
  }
  else
  {
    return false;
  }
}

void vReadSensorTask(void *pvParameters)
{
  Serial.println("STARTING SENSOR READS");
  int lightSignalCount = 0;
  unsigned long lastLightSignalTime = 0;
  bool isLightOnPreviously = false;

  while (1)
  {
    int STATE = currentState;

    if (isMovementDetected() && STATE == SLEEP)
    {
      // insertState(NORMAL);
      currentState = NORMAL;
      Serial.println(">>>>>>>>>>>>>>>>>>>>>>MOVEMENT DETECTED AND STATE=SLEEP  171");
      lastMovementTime = millis(); // Update the time of the last detected movement
      sleepTimeoutReached = false; // Clear the sleep-timeout flag
      weatherTimeoutReached = false;
    }
    else if (isMovementDetected() && STATE == NORMAL)
    {
      // insertState(MOVE);
      currentState = MOVE;
      Serial.println(">>>>>>>>>>>>>>>>>>>>>>>MOVEMENT DETECTED AND STATE == NORMAL 179");
      lastMovementTime = millis(); // Update the time of the last detected movement
      sleepTimeoutReached = false; // Clear the sleep-timeout flag
      weatherTimeoutReached = false;
    }
    else if (isMovementDetected() && STATE == WEATHER)
    {
      Serial.println(">>>>>>>>>>>>>>>>>>>>>>>>> MOVEMENT DETECTED AND STATE == WEATHER 93");
      lastMovementTime = millis(); // Update the time of the last detected movement
      sleepTimeoutReached = false; // Clear the sleep-timeout flag
      weatherTimeoutReached = false;
      currentState = NORMAL;
    }
    // Switch to the WEATHER state after 10 minutes with no movement
    if (millis() - lastMovementTime >= WEATHER_TIMEOUT && !weatherTimeoutReached)
    {
      // insertState(WEATHER);
      currentState = WEATHER;
      Serial.println(">>>>>>>>>>>>>>>>>>>>>>WEATHER after 10 minutes without movement");
      weatherTimeoutReached = true; // Mark the WEATHER timeout as reached
    }

    // Switch to the SLEEP state after an hour with no movement
    if (millis() - lastMovementTime >= SLEEP_TIMEOUT && !sleepTimeoutReached)
    {
      // insertState(SLEEP);
      currentState = SLEEP;
      Serial.println(">>>>>>>>>>>>>>>>>>>>>SLEEP after an hour without movement");
      sleepTimeoutReached = true; // Mark the SLEEP timeout as reached
    }

    if (STATE == MOVE && millis() - lastMovementTime >= 30000)
    {
      currentState = NORMAL;
      Serial.println(">>>>>>>>>>>>>>>>>>>>>BACK TO NORMAL after 30 seconds in MOVE");
    }

    // Switch to WEATHER if the light signal comes and goes 3 times
    if (!isLightOn())
    {
      // insertState(SLEEP);
      currentState = SLEEP;
      Serial.println("NO LIGHT --> SLEEP   160");
    }

    if (isLightOn())
    {
      if (!isLightOnPreviously)
      {
        lightSignalCount++;
        isLightOnPreviously = true;
        Serial.println("Light signal received");
      }
    }
    else
    {
      isLightOnPreviously = false;
    }

    if (lightSignalCount >= 3)
    {
      currentState = WEATHER;
      Serial.println(">>>>>>>>>>>>>>>>>>>>> Switching to WEATHER after the light signal came and went 3 times");
      lightSignalCount = 0; // Reset the counter
    }

    vTaskDelay(pdMS_TO_TICKS(500)); // Wait before polling the sensors again
  }
}

